mapper.select:
select device_id, model_path, feature_excel_path, real_excel_path, inline_data_json, update_time
from eq_wind_forecast_bind
where device_id = #{deviceId}

mapper.update:
update eq_wind_forecast_bind
set model_path = #{modelPath},
    feature_excel_path = #{featureExcelPath},
    real_excel_path = #{realExcelPath},
    inline_data_json = #{inlineDataJson}
where device_id = #{deviceId}
